        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        return c

    def two_opt(route):
        if len(route) < 4 or coords is None:
            return route[:]
        best = route[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            m = len(best)
            for i in range(m - 2):
                for j in range(i + 2, m):
                    if i == 0 and j == m - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost:
                        best = cand
                        best_cost = c
                        improved = True
                        break
                if improved:
                    break
        return best

    # Initial construction: deterministic sweep by angle when coordinates exist, otherwise by demand/ID.
    if coords is not None and n > 0:
        depot = point(0)
        ordered = []
        for c in customers:
            p = point(c)
            dx = p[0] - depot[0]
            dy = p[1] - depot[1]
            ang = 0.0
            if dx != 0.0 or dy != 0.0:
                ang = dy / (abs(dx) + abs(dy) + 1e-12)
                if dx < 0 and dy >= 0:
                    ang = 2.0 - ang
                elif dx < 0 and dy < 0:
                    ang = 4.0 - ang
                elif dx >= 0 and dy < 0:
                    ang = 6.0 + ang
            ordered.append((ang, dist(0, c), demands[c], c))
        ordered.sort()
        ordered = [c for _, _, _, c in ordered]
    else:
        ordered = sorted(customers, key=lambda c: (-demands[c], c))

    routes = []
    cur = []
    load = 0
    for c in ordered:
        d = demands[c]
        if d > capacity:
            # hard repair: put alone; infeasible demands are unavoidable, but keep customer served.
            if cur:
                routes.append(cur)
                cur = []
                load = 0
            routes.append([c])
            continue
        if cur and load + d > capacity:
            routes.append(cur)
            cur = []
            load = 0
        cur.append(c)
        load += d
    if cur:
        routes.append(cur)

    # Route improvement: orient each route to minimize depot ends.
    for idx in range(len(routes)):
        r = routes[idx]
        if len(r) >= 2 and coords is not None:
            if dist(0, r[-1]) + dist(r[0], 0) < dist(0, r[0]) + dist(r[-1], 0):
                routes[idx] = r[::-1]

    # Intra-route 2-opt.
    for idx in range(len(routes)):
        routes[idx] = two_opt(routes[idx])

    # Inter-route improvement by relocations and end-exchanges.
    improved = True
    while improved:
        improved = False
        best_delta = 0.0
        best_move = None

        for i in range(len(routes)):
            ri = routes[i]
            li = route_load(ri)
            for j in range(len(routes)):
                if i == j:
                    continue
                rj = routes[j]
                lj = route_load(rj)

                # relocate one customer from ends/middle of ri into any position in rj
                for pos_i in range(len(ri)):
                    c = ri[pos_i]
                    dc = demands[c]
                    if lj + dc > capacity:
                        continue
                    ri_prev = ri[pos_i - 1] if pos_i > 0 else 0
                    ri_next = ri[pos_i + 1] if pos_i + 1 < len(ri) else 0
                    remove_delta = dist(ri_prev, c) + dist(c, ri_next) - dist(ri_prev, ri_next)

                    for pos_j in range(len(rj) + 1):
                        rj_prev = rj[pos_j - 1] if pos_j > 0 else 0
                        rj_next = rj[pos_j] if pos_j < len(rj) else 0
                        insert_delta = dist(rj_prev, c) + dist(c, rj_next) - dist(rj_prev, rj_next)
                        delta = insert_delta - remove_delta
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best_move = ("relocate", i, j, pos_i, pos_j)

                # swap one customer if capacity allows
                for pos_i in range(len(ri)):
                    a = ri[pos_i]
                    da = demands[a]
                    ri_prev = ri[pos_i - 1] if pos_i > 0 else 0
                    ri_next = ri[pos_i + 1] if pos_i + 1 < len(ri) else 0
                    rem_i = dist(ri_prev, a) + dist(a, ri_next) - dist(ri_prev, ri_next)
                    for pos_j in range(len(rj)):
                        b = rj[pos_j]
                        db = demands[b]
                        if li - da + db > capacity or lj - db + da > capacity:
                            continue
                        rj_prev = rj[pos_j - 1] if pos_j > 0 else 0
                        rj_next = rj[pos_j + 1] if pos_j + 1 < len(rj) else 0
                        rem_j = dist(rj_prev, b) + dist(b, rj_next) - dist(rj_prev, rj_next)
                        add_i = dist(ri_prev, b) + dist(b, ri_next) - dist(ri_prev, ri_next)
                        add_j = dist(rj_prev, a) + dist(a, rj_next) - dist(rj_prev, rj_next)
                        delta = (add_i + add_j) - (rem_i + rem_j)
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best_move = ("swap", i, j, pos_i, pos_j)

        if best_move is not None:
            typ, i, j, pi, pj = best_move
            if typ == "relocate":
                c = routes[i][pi]
                routes[i].pop(pi)
                routes[j].insert(pj, c)
            else:
                a = routes[i][pi]
                b = routes[j][pj]
                routes[i][pi] = b
                routes[j][pj] = a
            routes = [r for r in routes if r]
            for idx in range(len(routes)):
                routes[idx] = two_opt(routes[idx])
            improved = True

    # Final normalization and deterministic cleanup.
    routes = [r for r in routes if r]
    for idx in range(len(routes)):
        if len(routes[idx]) >= 2 and coords is not None:
            r = routes[idx]
            if dist(0, r[-1]) + dist(r[0], 0) < dist(0, r[0]) + dist(r[-1], 0):
                routes[idx] = r[::-1]
    return routes
